def update(self, kwargs):
    # Update bbox last as it depends on font properties.
    sentinel = object()  # bbox can be None, so use another sentinel.
    bbox = kwargs.pop("bbox", sentinel)

    # Ensure keywords are processed correctly for fonts
    font_properties = {}
    # Handle font properties and any other keyword arguments
    for key, value in kwargs.items():
        if key in ['size', 'fontproperties']:
            font_properties[key] = value
        else:
            # Handle other properties or raise an error
            self.set_property(key, value)  # Assuming a method to set other properties

    super().update(font_properties)  # Call super with font-specific properties

    # Update bbox if it exists
    if bbox is not sentinel:
        self.set_bbox(bbox)
